settings.custom_liquid:
{%- assign badge1 = product.metafields.custom.product_badge_1.value -%}
{%- assign badge2 = product.metafields.custom.product_badge_2.value -%}
{%- if badge1 != blank or badge2 != blank -%}
<div class="ft-tags-row" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:2px;">
  {%- if badge1 != blank -%}
    <span style="display:inline-flex;align-items:center;background:#e11d2a;color:#fff;font-size:11px;font-weight:700;letter-spacing:1.32px;text-transform:uppercase;padding:6px 10px;border-radius:4px;line-height:1;">{{ badge1 }}</span>
  {%- endif -%}
  {%- if badge2 != blank -%}
    <span style="display:inline-flex;align-items:center;background:#fff;color:#0b0c0e;font-size:11px;font-weight:700;letter-spacing:1.32px;text-transform:uppercase;padding:5px 10px;border-radius:4px;border:1.5px solid #0b0c0e;line-height:1;">{{ badge2 }}</span>
  {%- endif -%}
</div>
{%- endif -%}

{%- assign about = product.metafields.custom.about -%}
{%- if about != blank -%}
<div class="ft-hook-wrap" style="border-left:3px solid #e11d2a;padding-left:16px;margin:2px 0;">
  <div style="font-size:16px;font-weight:500;line-height:1.5;color:#2a2d33;">{{ about | metafield_tag }}</div>
</div>
{%- endif -%}

{%- if product.compare_at_price > product.price -%}
  {%- assign savings = product.compare_at_price | minus: product.price -%}
  <div style="margin-top:-8px;">
    <span style="display:inline-flex;align-items:center;background:#e11d2a;color:#fff;font-size:11px;font-weight:700;letter-spacing:1.32px;text-transform:uppercase;padding:6px 10px;border-radius:4px;line-height:1;">SAVE {{ savings | money_without_trailing_zeros }}</span>
  </div>
{%- endif -%}
